```c
#include <stdio.h>
int main(void)
{
    int n, t, d, sum = 0;
    printf("Enter n: ");
    scanf("%d", &n);
    t = n;                      /* keep the original */
    while (t > 0) {
        d = t % 10;
        sum += d * d * d;       /* cube of each digit */
        t = t / 10;
    }
    if (sum == n)
        printf("%d is an Armstrong number\n", n);
    else
        printf("%d is not an Armstrong number\n", n);
    return 0;
}
```
For 153: $1 + 125 + 27 = 153$, so it is Armstrong.

