#include <stdio.h>

long power(int x, int n)
{
    if (n == 0)                 /* base case */
        return 1;
    return x * power(x, n - 1); /* x^n = x * x^(n-1) */
}

int main(void)
{
    int x, n;
    scanf("%d %d", &x, &n);
    printf("%d^%d = %ld\n", x, n, power(x, n));
    return 0;
}
```

```c
int gcd(int a, int b)
{
    if (b == 0)
        return a;
    return gcd(b, a % b);
}
```
Trace: gcd(48, 18) -> gcd(18, 12) -> gcd(12, 6) -> gcd(6, 0) returns 6.
So gcd(48, 18) = **6**.

