```c
#include <stdio.h>

struct student { char name[30]; float marks; };

int main(void)
{
    struct student s[20], t;
    int n, i, j;
    scanf("%d", &n);
    for (i = 0; i < n; i++)
        scanf("%s %f", s[i].name, &s[i].marks);
    for (i = 0; i < n - 1; i++)
        for (j = 0; j < n - 1 - i; j++)
            if (s[j].marks < s[j + 1].marks) {
                t = s[j];            /* whole structure swap */
                s[j] = s[j + 1];
                s[j + 1] = t;
            }
    for (i = 0; i < n; i++)
        printf("%s %.1f\n", s[i].name, s[i].marks);
    return 0;
}
```

